CREATE TABLE "stock_transfer" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"transfer_number" varchar(100) NOT NULL,"from_location_id" uuid NOT NULL,"to_location_id" uuid NOT NULL,"status" varchar(50) DEFAULT 'POSTED' NOT NULL,"transferred_at" timestamp NOT NULL,"note" text NOT NULL,"created_by_id" uuid NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL,CONSTRAINT "stock_transfer_transfer_number_unique" UNIQUE("transfer_number"));
CREATE TABLE "stock_count" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"count_number" varchar(100) NOT NULL,"inventory_location_id" uuid NOT NULL,"status" varchar(50) DEFAULT 'DRAFT' NOT NULL,"counted_at" timestamp NOT NULL,"note" text,"rejection_reason" text,"created_by_id" uuid NOT NULL,"submitted_at" timestamp,"approved_by_id" uuid,"approved_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL,CONSTRAINT "stock_count_count_number_unique" UNIQUE("count_number"));
ALTER TABLE "stock_movement" ADD COLUMN "movement_direction" varchar(20) DEFAULT 'NEUTRAL' NOT NULL;
ALTER TABLE "stock_movement" ADD COLUMN "reference_type" varchar(50);
ALTER TABLE "stock_movement" ADD COLUMN "reference_id" uuid;
CREATE TABLE "stock_transfer_item" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"stock_transfer_id" uuid NOT NULL,"material_id" uuid NOT NULL,"quantity" numeric(12,2) NOT NULL,"unit_cost" numeric(15,2) NOT NULL,"out_movement_id" uuid,"in_movement_id" uuid,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "stock_count_item" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"stock_count_id" uuid NOT NULL,"material_id" uuid NOT NULL,"system_quantity" numeric(12,2) NOT NULL,"counted_quantity" numeric(12,2) NOT NULL,"variance_quantity" numeric(12,2) NOT NULL,"unit_cost" numeric(15,2) NOT NULL,"stock_movement_id" uuid,"created_at" timestamp DEFAULT now() NOT NULL);
ALTER TABLE "goods_receipt" ADD COLUMN "reversal_reason" text;
ALTER TABLE "goods_receipt" ADD COLUMN "reversal_requested_by_id" uuid;
ALTER TABLE "goods_receipt" ADD COLUMN "reversal_requested_at" timestamp;
ALTER TABLE "goods_receipt" ADD COLUMN "reversed_by_id" uuid;
ALTER TABLE "goods_receipt" ADD COLUMN "reversed_at" timestamp;
ALTER TABLE "goods_receipt_item" ADD COLUMN "reversal_stock_movement_id" uuid;
ALTER TABLE "stock_transfer" ADD CONSTRAINT "stock_transfer_from_location_id_inventory_location_id_fk" FOREIGN KEY ("from_location_id") REFERENCES "public"."inventory_location"("id") ON DELETE restrict;
ALTER TABLE "stock_transfer" ADD CONSTRAINT "stock_transfer_to_location_id_inventory_location_id_fk" FOREIGN KEY ("to_location_id") REFERENCES "public"."inventory_location"("id") ON DELETE restrict;
ALTER TABLE "stock_transfer" ADD CONSTRAINT "stock_transfer_created_by_id_user_id_fk" FOREIGN KEY ("created_by_id") REFERENCES "public"."user"("id") ON DELETE restrict;
ALTER TABLE "stock_count" ADD CONSTRAINT "stock_count_inventory_location_id_inventory_location_id_fk" FOREIGN KEY ("inventory_location_id") REFERENCES "public"."inventory_location"("id") ON DELETE restrict;
ALTER TABLE "stock_count" ADD CONSTRAINT "stock_count_created_by_id_user_id_fk" FOREIGN KEY ("created_by_id") REFERENCES "public"."user"("id") ON DELETE restrict;
ALTER TABLE "stock_count" ADD CONSTRAINT "stock_count_approved_by_id_user_id_fk" FOREIGN KEY ("approved_by_id") REFERENCES "public"."user"("id") ON DELETE restrict;
ALTER TABLE "stock_transfer_item" ADD CONSTRAINT "stock_transfer_item_stock_transfer_id_stock_transfer_id_fk" FOREIGN KEY ("stock_transfer_id") REFERENCES "public"."stock_transfer"("id") ON DELETE cascade;
ALTER TABLE "stock_transfer_item" ADD CONSTRAINT "stock_transfer_item_material_id_material_master_id_fk" FOREIGN KEY ("material_id") REFERENCES "public"."material_master"("id") ON DELETE restrict;
ALTER TABLE "stock_transfer_item" ADD CONSTRAINT "stock_transfer_item_out_movement_id_stock_movement_id_fk" FOREIGN KEY ("out_movement_id") REFERENCES "public"."stock_movement"("id") ON DELETE restrict;
ALTER TABLE "stock_transfer_item" ADD CONSTRAINT "stock_transfer_item_in_movement_id_stock_movement_id_fk" FOREIGN KEY ("in_movement_id") REFERENCES "public"."stock_movement"("id") ON DELETE restrict;
ALTER TABLE "stock_count_item" ADD CONSTRAINT "stock_count_item_stock_count_id_stock_count_id_fk" FOREIGN KEY ("stock_count_id") REFERENCES "public"."stock_count"("id") ON DELETE cascade;
ALTER TABLE "stock_count_item" ADD CONSTRAINT "stock_count_item_material_id_material_master_id_fk" FOREIGN KEY ("material_id") REFERENCES "public"."material_master"("id") ON DELETE restrict;
ALTER TABLE "stock_count_item" ADD CONSTRAINT "stock_count_item_stock_movement_id_stock_movement_id_fk" FOREIGN KEY ("stock_movement_id") REFERENCES "public"."stock_movement"("id") ON DELETE restrict;
ALTER TABLE "goods_receipt" ADD CONSTRAINT "goods_receipt_reversal_requested_by_id_user_id_fk" FOREIGN KEY ("reversal_requested_by_id") REFERENCES "public"."user"("id") ON DELETE restrict;
ALTER TABLE "goods_receipt" ADD CONSTRAINT "goods_receipt_reversed_by_id_user_id_fk" FOREIGN KEY ("reversed_by_id") REFERENCES "public"."user"("id") ON DELETE restrict;
ALTER TABLE "goods_receipt_item" ADD CONSTRAINT "goods_receipt_item_reversal_stock_movement_id_stock_movement_id_fk" FOREIGN KEY ("reversal_stock_movement_id") REFERENCES "public"."stock_movement"("id") ON DELETE set null;
CREATE INDEX "st_from_location_idx" ON "stock_transfer"("from_location_id"); CREATE INDEX "st_to_location_idx" ON "stock_transfer"("to_location_id");
CREATE INDEX "sc_location_idx" ON "stock_count"("inventory_location_id"); CREATE INDEX "sc_status_idx" ON "stock_count"("status");
CREATE INDEX "sm_reference_idx" ON "stock_movement"("reference_type","reference_id");
CREATE INDEX "sti_transfer_idx" ON "stock_transfer_item"("stock_transfer_id"); CREATE INDEX "sti_material_idx" ON "stock_transfer_item"("material_id");
CREATE UNIQUE INDEX "sci_count_material_uidx" ON "stock_count_item"("stock_count_id","material_id"); CREATE INDEX "sci_count_idx" ON "stock_count_item"("stock_count_id");
